  -- Lesson 22: দরকারি ২০টি Sentence Pattern

  values (v_part_1, 'দরকারি ২০টি Sentence Pattern', 'lesson-22', 'Lesson 22 from English Foundation.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"যা জানলে ইংরেজি হঠাৎ উন্নত শোনায়"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 এই Lesson শেষে তুমি যা পারবে"}]},{"type":"paragraph","content":[{"type":"text","text":"১. অতীতের অভ্যাস বলতে পারবে (I used to play cricket)।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. পরামর্শ ও পছন্দ প্রকাশ করতে পারবে (had better, would rather)।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. ভদ্রভাবে অনুরোধ করতে পারবে (Would you mind…?)।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. আফসোস প্রকাশ করতে পারবে (I wish I were…)।"}]},{"type":"paragraph","content":[{"type":"text","text":"৫. ২০টি তৈরি কাঠামো পাবে — শুধু শব্দ বসিয়ে দিলেই বাক্য তৈরি।"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"💡 এই Lesson কেন আলাদা? এতদিন তুমি নিয়ম শিখেছ। আজ শিখবে তৈরি কাঠামো (pattern) — যেগুলো ইংরেজিভাষীরা হুবহু এভাবেই বলে। একটা pattern শিখলে সেটা দিয়ে শত শত বাক্য বানানো যায়। এটাই দ্রুত উন্নতির সবচেয়ে সহজ পথ।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ১ — অভ্যাস ও অতীত"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১.১ used to — অতীতের অভ্যাস (এখন আর নেই)"}]},{"type":"paragraph","content":[{"type":"text","text":"Subject  +  used to  +  Verb (মূল রূপ)"}]},{"type":"paragraph","content":[{"type":"text","text":"উচ্চারণ: ইউজড টু /ˈjuːst tuː/"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"I used to play cricket in my childhood.  →  ছোটবেলায় আমি ক্রিকেট খেলতাম।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"He used to smoke, but now he does not.  →  সে ধূমপান করত, কিন্তু এখন করে না।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"We used to live in a village.  →  আমরা গ্রামে থাকতাম।"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"না-বাচক: I did not use to smoke.   প্রশ্ন: Did you use to play?  (এখানে \"used\" নয়, \"use\")"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১.২ be used to — অভ্যস্ত হওয়া (সম্পূর্ণ ভিন্ন অর্থ!)"}]},{"type":"paragraph","content":[{"type":"text","text":"Subject  +  am / is / are  +  used to  +  Verb + ing"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"I am used to getting up early.  →  আমি সকালে ওঠায় অভ্যস্ত।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"He is used to the noise.  →  সে শব্দে অভ্যস্ত।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🚨 দুটো গুলিয়ে ফেলা যাবে না I used to get up early.  = আগে উঠতাম (এখন উঠি না) I am used to getting up early.  = আমি এতে অভ্যস্ত (এখনো উঠি) পার্থক্য: প্রথমটায় \"to\"-এর পরে মূল verb, দ্বিতীয়টায় verb + ing।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১.৩ would rather — বরং"}]},{"type":"paragraph","content":[{"type":"text","text":"Subject  +  would rather  +  Verb (মূল রূপ)  +  than  +  Verb"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"I would rather stay home than go out.  →  আমি বাইরে যাওয়ার চেয়ে বাসায় থাকতে চাই।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"He would rather die than beg.  →  সে ভিক্ষা করার চেয়ে মরতে চায়।"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১.৪ had better — উচিত (সতর্কতাসহ)"}]},{"type":"paragraph","content":[{"type":"text","text":"Subject  +  had better  +  Verb (মূল রূপ)"}]},{"type":"paragraph","content":[{"type":"text","text":"should-এর চেয়ে জোরালো — না করলে খারাপ কিছু হতে পারে, এমন ভাব থাকে।"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You had better see a doctor.  →  তোমার ডাক্তার দেখানোই ভালো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You had better not go there.  →  তোমার সেখানে না যাওয়াই ভালো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"We''d better hurry.  →  আমাদের তাড়াতাড়ি করা উচিত।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"⚠️ had better-এর পরে \"to\" বসে না → ❌ You had better to go"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ২ — অনুরোধ ও প্রস্তাব"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২.১ Would you mind + verb-ing? — ভদ্র অনুরোধ"}]},{"type":"paragraph","content":[{"type":"text","text":"Would you mind  +  Verb + ing  ?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Would you mind closing the door?  →  দরজাটা বন্ধ করবেন কি?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Would you mind helping me?  →  আমাকে একটু সাহায্য করবেন?"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"⚠️ উত্তর দেওয়ার সময় সতর্ক \"Would you mind…?\" মানে \"আপনার আপত্তি আছে কি?\" — তাই রাজি হলে \"No\" বলতে হয়!"}]},{"type":"paragraph","content":[{"type":"text","text":"✅ No, not at all.  = ঠিক আছে, করছি।"}]},{"type":"paragraph","content":[{"type":"text","text":"✅ Of course not.  = কোনো সমস্যা নেই।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২.২ Let''s — চলো"}]},{"type":"paragraph","content":[{"type":"text","text":"Let''s  +  Verb (মূল রূপ)"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Let''s go to the market.  →  চলো বাজারে যাই।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Let''s start now.  →  চলো এখনই শুরু করি।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Let''s not waste time.  →  চলো সময় নষ্ট না করি।"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২.৩ Shall we…? / Why don''t we…? — প্রস্তাব"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Shall we go now?  →  আমরা কি এখন যাব?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Why don''t we take a break?  →  আমরা একটু বিরতি নিই না কেন?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How about going out?  →  বাইরে গেলে কেমন হয়?"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২.৪ It is time + Past Tense — এখন সময়"}]},{"type":"paragraph","content":[{"type":"text","text":"It is time  +  Subject  +  Past Tense"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It is time you went to bed.  →  তোমার এখন ঘুমাতে যাওয়ার সময়।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It is high time we started.  →  আমাদের শুরু করার এখনই উপযুক্ত সময়।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"📌 অদ্ভুত মনে হলেও এখানে Past Tense বসে — এটাই নিয়ম।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৩ — ইচ্ছা ও আফসোস"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৩.১ I wish — ইশ্‌"}]},{"type":"paragraph","content":[{"type":"text","text":"I wish  +  Subject  +  Past Tense  (বর্তমানের আফসোস)"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"I wish I were rich.  →  ইশ্‌, যদি আমি ধনী হতাম।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"I wish I knew English well.  →  ইশ্‌, যদি ইংরেজি ভালো জানতাম।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"I wish he were here.  →  ইশ্‌, সে যদি এখানে থাকত।"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"I wish  +  Subject  +  had  +  V3  (অতীতের আফসোস)"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"I wish I had studied harder.  →  ইশ্‌, যদি আরও পড়তাম।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"I wish I had not said that.  →  ইশ্‌, যদি ওটা না বলতাম।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"📌 Lesson 17-এর মতোই — এখানেও সবার জন্য \"were\" বসে, \"was\" নয়।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৪ — পরিমাণ ও ফলাফল"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৪.১ so … that / such … that — এত … যে"}]},{"type":"paragraph","content":[{"type":"text","text":"so  +  adjective  +  that              such  +  a/an + adjective + noun  +  that"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"He is so weak that he cannot walk.  →  সে এত দুর্বল যে হাঁটতে পারে না।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It was so hot that we stayed inside.  →  এত গরম ছিল যে আমরা ভেতরে থাকলাম।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"He is such a good boy that everyone likes him.  →  সে এত ভালো ছেলে যে সবাই তাকে পছন্দ করে।"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৪.২ too … to / enough to"}]},{"type":"paragraph","content":[{"type":"text","text":"too  +  adjective  +  to  +  verb          adjective  +  enough  +  to  +  verb"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"He is too weak to walk.  →  সে হাঁটার মতো যথেষ্ট শক্তিশালী নয়। (খুব দুর্বল)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"He is strong enough to carry it.  →  সে এটা বহন করার মতো যথেষ্ট শক্তিশালী।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"This tea is too hot to drink.  →  এই চা খাওয়ার মতো নয়, খুব গরম।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🧠 একই কথা তিনভাবে He is so weak that he cannot walk. He is too weak to walk. He is not strong enough to walk. পরীক্ষায় প্রায়ই এই তিনটির মধ্যে রূপান্তর করতে বলা হয়।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৪.৩ as soon as / no sooner … than — যেই না … অমনি"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"As soon as I reached, it started raining.  →  আমি পৌঁছাতেই বৃষ্টি শুরু হলো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No sooner had I reached than it started raining.  →  আমি পৌঁছানোমাত্রই বৃষ্টি শুরু হলো।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"📌 No sooner দিয়ে বাক্য শুরু হলে পরে \"had + subject\" বসে, আর \"than\" আসে (then নয়)।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৫ — জোড়া শব্দ (Correlatives)"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"অর্থ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"both … and"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"উভয়ই"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He is both intelligent and hard-working."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"either … or"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"হয় … নয়"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Either he or I will go."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"neither … nor"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"না … না"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Neither he nor I went there."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"not only … but also"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শুধু নয় … বরং"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He is not only rich but also kind."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"as … as"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সমান"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He is as tall as his brother."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"the more … the more"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"যত … তত"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"The more you read, the more you learn."}}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"⚠️ neither … nor-এ আর \"not\" বসে না → ❌ Neither he nor I did not go."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৬ — আরও ৫টি দরকারি Pattern"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"গঠন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"It is + adj + to"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"It is easy to say."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"It is difficult to learn English quickly."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"There is no use + ing"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কোনো লাভ নেই"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"There is no use crying over spilt milk."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"It takes + সময় + to"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সময় লাগে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"It takes two hours to reach Dhaka."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"have something done"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"করানো"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I had my hair cut yesterday."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"keep + ing"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"করতেই থাকা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He kept talking for an hour."}}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৭ — ৮টি Common Mistake"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"❌ ভুল"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ শুদ্ধ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কারণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"You had better to go."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"You had better go."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"had better-এর পরে \"to\" নেই।"}]}]}]},{"type":"tableRow","content":[{"type":"ta