ontent":[{"type":"text","text":"প্রশ্ন ১ — সঠিক রূপ বসাও (Tense)        নম্বর: ১৫"}]},{"type":"paragraph","content":[{"type":"text","text":"1. He ______ (go) to school every day."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Look! It ______ (rain) now."}]},{"type":"paragraph","content":[{"type":"text","text":"3. I ______ (eat) rice an hour ago."}]},{"type":"paragraph","content":[{"type":"text","text":"4. She ______ (finish) her work already."}]},{"type":"paragraph","content":[{"type":"text","text":"5. They ______ (play) football tomorrow."}]},{"type":"paragraph","content":[{"type":"text","text":"6. While I ______ (cook), he came."}]},{"type":"paragraph","content":[{"type":"text","text":"7. He ______ (live) here for ten years."}]},{"type":"paragraph","content":[{"type":"text","text":"8. The sun ______ (rise) in the east."}]},{"type":"paragraph","content":[{"type":"text","text":"9. I ______ (not see) him yesterday."}]},{"type":"paragraph","content":[{"type":"text","text":"10. We ______ (be) friends since childhood."}]},{"type":"paragraph","content":[{"type":"text","text":"11. He said he ______ (be) ill."}]},{"type":"paragraph","content":[{"type":"text","text":"12. If it ______ (rain), I will not go."}]},{"type":"paragraph","content":[{"type":"text","text":"13. She ______ (write) a letter now."}]},{"type":"paragraph","content":[{"type":"text","text":"14. They ______ (leave) before I reached."}]},{"type":"paragraph","content":[{"type":"text","text":"15. I ______ (call) you tomorrow."}]},{"type":"paragraph","content":[{"type":"text","text":"প্রশ্ন ২ — না-বাচক ও প্রশ্নে বদলাও        নম্বর: ১০"}]},{"type":"paragraph","content":[{"type":"text","text":"1. He goes to school.  (না-বাচক)"}]},{"type":"paragraph","content":[{"type":"text","text":"2. They are playing.  (না-বাচক)"}]},{"type":"paragraph","content":[{"type":"text","text":"3. She has finished the work.  (না-বাচক)"}]},{"type":"paragraph","content":[{"type":"text","text":"4. He went to Dhaka.  (না-বাচক)"}